window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["bias-fairness"]={"title":"偏见与公平：先选择要保护的关系，再计算群体差异","subtitle":"用同一招聘案例理解代表性偏差、标签偏差、代理变量、人口统计平等、均等机会、校准及其不可兼得边界。","thesis":"公平没有一个脱离情境的万能指标；必须先明确<b>谁受到什么决策、哪类错误更伤人、基准标签是否正当、要保护哪一种关系</b>，再选择指标、干预和申诉机制。","quality":{"contractVersion":2,"formulas":[{"id":"bias-fairness-formula-1","section":2,"formulaIndex":1,"symbols":[{"name":"T","meaning":"公式中的“T”是本节计算所使用的量，具体角色由紧邻文字定义。","evidence":"两组各100名候选人的筛选结果 案例手算 总体准确率相同"}]}],"examples":[{"section":2,"evidence":{"setup":"两组各100名候选人的筛选结果 案例手算 总体准确率相同","rule":"为什么群体经历仍可能完全不同","steps":"A组有40名真正合格者","interpretation":"系统通过32名合格者并误通过12名不合格者"}}],"termReviews":[],"sectionContracts":[{"section":2,"definition":{"answer":"本节对“完整示例：两组各100名候选人的筛选结果”的界定是：两组各100名候选人的筛选结果 案例手算 总体准确率相同","evidence":"两组各100名候选人的筛选结果 案例手算 总体准确率相同"},"problem":{"answer":"本节处理的实际问题是：为什么群体经历仍可能完全不同","evidence":"为什么群体经历仍可能完全不同"},"inputOutput":{"answer":"本节的输入与输出关系是：A组有40名真正合格者","evidence":"A组有40名真正合格者"},"mechanism":{"answer":"本节给出的工作机制是：系统通过32名合格者并误通过12名不合格者","evidence":"系统通过32名合格者并误通过12名不合格者"},"interpretation":{"answer":"本节要求这样解释结果：TPR=32/40= 80%","evidence":"TPR=32/40= 80%"},"boundary":{"answer":"本节明确的适用边界是：FPR=12/60= 20%","evidence":"FPR=12/60= 20%"}},{"section":3,"definition":{"answer":"本节对“三个常用定义保护不同关系”的界定是：3 三个常用定义保护不同关系 指标 人口统计平等、均等机会和校准分别忽略了什么","evidence":"3 三个常用定义保护不同关系 指标 人口统计平等、均等机会和校准分别忽略了什么"},"problem":{"answer":"本节处理的实际问题是：定义 要求 适合关注 可能代价 人口统计平等 P(通过|组)相近 资源分配结果 忽略资格/标签差异与标签正当性 均等机会 各组TPR相近 合格者获得机会 不约束FPR 均等赔率 TPR与FPR都相近 两类错误 可能需组别阈值或降精度 组内校准 同分数对应相同真实率 风险分数含义 基率不同时难兼顾等错误率 指标选择要在部署前由业务、领域专家和受影响群体共同讨论","evidence":"定义 要求 适合关注 可能代价 人口统计平等 P(通过|组)相近 资源分配结果 忽略资格/标签差异与标签正当性 均等机会 各组TPR相近 合格者获得机会 不约束FPR 均等赔率 TPR与FPR都相近 两类错误 可能需组别阈值或降精度 组内校准 同分数对应相同真实率 风险分数含义 基率不同时难兼顾等错误率 指标选择要在部署前由业务、领域专家和受影响群体共同讨论"},"inputOutput":{"answer":"本节的输入与输出关系是：而不是事后挑最漂亮的一项","evidence":"而不是事后挑最漂亮的一项"},"mechanism":{"answer":"本节给出的工作机制是：3 三个常用定义保护不同关系 指标","evidence":"3 三个常用定义保护不同关系 指标"},"interpretation":{"answer":"本节要求这样解释结果：口统计平等、均等机会和校准分别忽略了","evidence":"口统计平等、均等机会和校准分别忽略了"},"boundary":{"answer":"本节明确的适用边界是：么？ 定义 要求 适合关注 可能代价","evidence":"么？ 定义 要求 适合关注 可能代价"}},{"section":4,"definition":{"answer":"本节对“公平定义在不同基率下通常不能全部同时满足”的界定是：4 公平定义在不同基率下通常不能全部同时满足 不可兼得 为什么把所有群体指标都设成相等会得到矛盾目标","evidence":"4 公平定义在不同基率下通常不能全部同时满足 不可兼得 为什么把所有群体指标都设成相等会得到矛盾目标"},"problem":{"answer":"本节处理的实际问题是：若两组真实正例率不同","evidence":"若两组真实正例率不同"},"inputOutput":{"answer":"本节的输入与输出关系是：而评分在各组内都校准","evidence":"而评分在各组内都校准"},"mechanism":{"answer":"本节给出的工作机制是：则高分人群的正例比例必须反映各自基率","evidence":"则高分人群的正例比例必须反映各自基率"},"interpretation":{"answer":"本节要求这样解释结果：除非预测完美或基率相同","evidence":"除非预测完美或基率相同"},"boundary":{"answer":"本节明确的适用边界是：要同时强制相同TPR和FPR","evidence":"要同时强制相同TPR和FPR"}},{"section":5,"definition":{"answer":"本节对“原创图：偏差沿问题、数据、模型、人机决策与反馈循环传播”的界定是：问题定义 谁的哪种伤害 数据/标签 代表性/测量 历史选择 模型分数 代理变量 总体目标 阈值+人 界面/采纳率 申诉 现实结果 机会/伤害 新训练数据 选择性标签与反馈","evidence":"问题定义 谁的哪种伤害 数据/标签 代表性/测量 历史选择 模型分数 代理变量 总体目标 阈值+人 界面/采纳率 申诉 现实结果 机会/伤害 新训练数据 选择性标签与反馈"},"problem":{"answer":"本节处理的实际问题是：偏差沿问题、数据、模型、人机决策与反馈循环传播 可视化 为什么只做训练集去偏","evidence":"偏差沿问题、数据、模型、人机决策与反馈循环传播 可视化 为什么只做训练集去偏"},"inputOutput":{"answer":"本节的输入与输出关系是：部署后差距还会回来","evidence":"部署后差距还会回来"},"mechanism":{"answer":"本节给出的工作机制是：过去没被录用者的真实表现不可见 图 1 公平是端到端属性","evidence":"过去没被录用者的真实表现不可见 图 1 公平是端到端属性"},"interpretation":{"answer":"本节要求这样解释结果：任何一站都可能制造或放大差距","evidence":"任何一站都可能制造或放大差距"},"boundary":{"answer":"本节明确的适用边界是：5 原创图：偏差沿问题、数据、模型、","evidence":"5 原创图：偏差沿问题、数据、模型、"}},{"section":6,"definition":{"answer":"本节对“标签可能记录历史决策，而不是真实目标”的界定是：而不是真实目标 测量偏差 用“过去被录用且绩效高”训练","evidence":"而不是真实目标 测量偏差 用“过去被录用且绩效高”训练"},"problem":{"answer":"本节处理的实际问题是：6 标签可能记录历史决策","evidence":"6 标签可能记录历史决策"},"inputOutput":{"answer":"本节的输入与输出关系是：模型到底学到了什么","evidence":"模型到底学到了什么"},"mechanism":{"answer":"本节给出的工作机制是：未录用者没有绩效标签","evidence":"未录用者没有绩效标签"},"interpretation":{"answer":"本节要求这样解释结果：观察到的结果受到旧流程选择","evidence":"观察到的结果受到旧流程选择"},"boundary":{"answer":"本节明确的适用边界是：绩效评分还受经理、岗位机会和留任影响","evidence":"绩效评分还受经理、岗位机会和留任影响"}},{"section":7,"definition":{"answer":"本节对“交叉群体揭示平均指标掩盖的小群体失败”的界定是：7 交叉群体揭示平均指标掩盖的小群体失败 切片 男女差距很小","evidence":"7 交叉群体揭示平均指标掩盖的小群体失败 切片 男女差距很小"},"problem":{"answer":"本节处理的实际问题是：是否说明所有女性都被公平对待","evidence":"是否说明所有女性都被公平对待"},"inputOutput":{"answer":"本节的输入与输出关系是：性别与年龄、地域、残障、语言等交叉后","evidence":"性别与年龄、地域、残障、语言等交叉后"},"mechanism":{"answer":"本节给出的工作机制是：某小群体可能承受严重错误","evidence":"某小群体可能承受严重错误"},"interpretation":{"answer":"本节要求这样解释结果：切片过细又会样本不足、置信区间极宽","evidence":"切片过细又会样本不足、置信区间极宽"},"boundary":{"answer":"本节明确的适用边界是：并增加隐私风险","evidence":"并增加隐私风险"}},{"section":8,"definition":{"answer":"本节对“缓解可以发生在数据、学习、阈值和流程四层”的界定是：8 缓解可以发生在数据、学习、阈值和流程四层 干预 哪一层修复最不容易制造新的不可解释差异","evidence":"8 缓解可以发生在数据、学习、阈值和流程四层 干预 哪一层修复最不容易制造新的不可解释差异"},"problem":{"answer":"本节处理的实际问题是：数据层改善覆盖、标签和采样","evidence":"数据层改善覆盖、标签和采样"},"inputOutput":{"answer":"本节的输入与输出关系是：学习层加权或约束目标","evidence":"学习层加权或约束目标"},"mechanism":{"answer":"本节给出的工作机制是：重采样不能修错误标签","evidence":"重采样不能修错误标签"},"interpretation":{"answer":"本节要求这样解释结果：后处理调整阈值","evidence":"后处理调整阈值"},"boundary":{"answer":"本节明确的适用边界是：流程层改变用途、提供申诉或保证资源","evidence":"流程层改变用途、提供申诉或保证资源"}},{"section":9,"definition":{"answer":"本节对“人类复核可能缓解也可能放大模型偏差”的界定是：9 人类复核可能缓解也可能放大模型偏差 人机系统 加一个招聘官确认按钮","evidence":"9 人类复核可能缓解也可能放大模型偏差 人机系统 加一个招聘官确认按钮"},"problem":{"answer":"本节处理的实际问题是：为什么差距可能反而增加","evidence":"为什么差距可能反而增加"},"inputOutput":{"answer":"本节的输入与输出关系是：人会锚定模型分数、只审查模型标记的样本","evidence":"人会锚定模型分数、只审查模型标记的样本"},"mechanism":{"answer":"本节给出的工作机制是：或对不同群体采用不同推翻标准","evidence":"或对不同群体采用不同推翻标准"},"interpretation":{"answer":"本节要求这样解释结果：界面若隐藏不确定性并显示伪精确排名","evidence":"界面若隐藏不确定性并显示伪精确排名"},"boundary":{"answer":"本节明确的适用边界是：自动化偏见更强","evidence":"自动化偏见更强"}},{"section":10,"definition":{"answer":"本节对“上线监控需要处理延迟标签和行为反馈”的界定是：10 上线监控需要处理延迟标签和行为反馈 持续验证 职位变化后","evidence":"10 上线监控需要处理延迟标签和行为反馈 持续验证 职位变化后"},"problem":{"answer":"本节处理的实际问题是：旧评测集为何很快失效","evidence":"旧评测集为何很快失效"},"inputOutput":{"answer":"本节的输入与输出关系是：岗位、申请人群和招聘官行为变化会改变输入和基率","evidence":"岗位、申请人群和招聘官行为变化会改变输入和基率"},"mechanism":{"answer":"本节给出的工作机制是：监测输入覆盖、分数分布、群体通过/推翻/申诉、反馈缺失和标签延迟","evidence":"监测输入覆盖、分数分布、群体通过/推翻/申诉、反馈缺失和标签延迟"},"interpretation":{"answer":"本节要求这样解释结果：真实绩效可能数月后才出现","evidence":"真实绩效可能数月后才出现"},"boundary":{"answer":"本节明确的适用边界是：且只对被录用者可见","evidence":"且只对被录用者可见"}},{"section":11,"definition":{"answer":"本节对“公平评测要报告绝对量、相对差距与不确定性”的界定是：并说明标签与群体定义","evidence":"并说明标签与群体定义"},"problem":{"answer":"本节处理的实际问题是：11 公平评测要报告绝对量、相对差距与不确定性 评测 比率0.8和差值2个百分点","evidence":"11 公平评测要报告绝对量、相对差距与不确定性 评测 比率0.8和差值2个百分点"},"inputOutput":{"answer":"本节的输入与输出关系是：比率对低基率敏感","evidence":"比率对低基率敏感"},"mechanism":{"answer":"本节给出的工作机制是：差值展示实际规模","evidence":"差值展示实际规模"},"interpretation":{"answer":"本节要求这样解释结果：二者都要配分母、置信区间和伤害严重度","evidence":"二者都要配分母、置信区间和伤害严重度"},"boundary":{"answer":"本节明确的适用边界是：至少报告选择率、TPR、FPR、PPV、校准、最坏群体、交叉切片和随时间稳定性","evidence":"至少报告选择率、TPR、FPR、PPV、校准、最坏群体、交叉切片和随时间稳定性"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分数据偏差、测量偏差和部署反馈；从混淆矩阵手算群体公平指标；解释公平定义冲突的原因；设计交叉群体与不确定性评测；把技术指标连接到真实补救。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">1</span>偏见不是模型里的一颗坏参数，而是一条因果链<span class=\"dd-badge intuition\">问题定义</span></h2><p class=\"dd-lead\">训练集男女数量相等，系统就公平了吗？</p><p>样本数平衡不能修复招聘历史本身的歧视、绩效标签的测量误差、职位广告触达差异或录用后的机会差异。偏差可来自问题定义、采样、标签、特征、目标函数、阈值、界面和部署后的反馈。</p><p>先写受影响者、决策、收益与伤害：漏掉合格者和误收不合格者代价不同，候选人与雇主的视角也不同。公平分析是规范选择加经验测量，不能让一个指标替代价值判断。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>完整示例：两组各100名候选人的筛选结果<span class=\"dd-badge math\">案例手算</span></h2><p class=\"dd-lead\">总体准确率相同，为什么群体经历仍可能完全不同？</p><p>A组有40名真正合格者，系统通过32名合格者并误通过12名不合格者：TPR=32/40=<b>80%</b>，FPR=12/60=<b>20%</b>，通过率44%。B组有20名真正合格者，通过12名合格者并误通过8名不合格者：TPR=12/20=<b>60%</b>，FPR=8/80=<b>10%</b>，通过率20%。</p><div class=\"dd-formula\" data-formula-id=\"bias-fairness-formula-1\" data-display=\"mathml\"><math display=\"block\" aria-label=\"均等机会差距 = TPR_A − TPR_B = 0.80 − 0.60 = 0.20\"><mrow><mtext>均等机会差距</mtext><mspace width=\"0.35em\"/><mo>=</mo><mspace width=\"0.35em\"/><msub><mi>TPR</mi><mi>A</mi></msub><mspace width=\"0.35em\"/><mo>−</mo><mspace width=\"0.35em\"/><msub><mi>TPR</mi><mi>B</mi></msub><mspace width=\"0.35em\"/><mo>=</mo><mspace width=\"0.35em\"/><mn>0.80</mn><mspace width=\"0.35em\"/><mo>−</mo><mspace width=\"0.35em\"/><mn>0.60</mn><mspace width=\"0.35em\"/><mo>=</mo><mspace width=\"0.35em\"/><mn>0.20</mn></mrow></math></div><p>A组误收更多，B组合格者被漏掉更多；问“哪组更公平”必须说明优先保护机会、错误率还是个体风险分数含义。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>三个常用定义保护不同关系<span class=\"dd-badge eng\">指标</span></h2><p class=\"dd-lead\">人口统计平等、均等机会和校准分别忽略了什么？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>定义</th><th>要求</th><th>适合关注</th><th>可能代价</th></tr></thead><tbody><tr><td>人口统计平等</td><td>P(通过|组)相近</td><td>资源分配结果</td><td>忽略资格/标签差异与标签正当性</td></tr><tr><td>均等机会</td><td>各组TPR相近</td><td>合格者获得机会</td><td>不约束FPR</td></tr><tr><td>均等赔率</td><td>TPR与FPR都相近</td><td>两类错误</td><td>可能需组别阈值或降精度</td></tr><tr><td>组内校准</td><td>同分数对应相同真实率</td><td>风险分数含义</td><td>基率不同时难兼顾等错误率</td></tr></tbody></table></div><p>指标选择要在部署前由业务、领域专家和受影响群体共同讨论，而不是事后挑最漂亮的一项。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>公平定义在不同基率下通常不能全部同时满足<span class=\"dd-badge math\">不可兼得</span></h2><p class=\"dd-lead\">为什么把所有群体指标都设成相等会得到矛盾目标？</p><p>若两组真实正例率不同，而评分在各组内都校准，则高分人群的正例比例必须反映各自基率。要同时强制相同TPR和FPR，除非预测完美或基率相同，分数分布和预测值会被拉向冲突约束。</p><p>这不是“公平做不到”，而是说明不同定义表达不同道德关系。团队必须说明优先级、剩余伤害和补救，而不能用数学定理逃避选择。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>不可兼得不意味着随便选指标；它要求把价值取舍公开并接受审查。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：偏差沿问题、数据、模型、人机决策与反馈循环传播<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么只做训练集去偏，部署后差距还会回来？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 760 335\" role=\"img\" aria-label=\"公平风险从问题定义、数据标签、模型分数、阈值与人类决策到结果反馈的循环\"><defs><marker id=\"bf30\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0L6,3L0,6z\" fill=\"#7f8b9d\"/></marker></defs><rect x=\"22\" y=\"93\" width=\"112\" height=\"92\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"78\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\">问题定义</text><text x=\"78\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">谁的哪种伤害</text><path d=\"M134 139H166\" stroke=\"#7f8b9d\" marker-end=\"url(#bf30)\"/><rect x=\"171\" y=\"73\" width=\"112\" height=\"132\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"227\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\">数据/标签</text><text x=\"227\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">代表性/测量</text><text x=\"227\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\">历史选择</text><path d=\"M283 139H315\" stroke=\"#7f8b9d\" marker-end=\"url(#bf30)\"/><rect x=\"320\" y=\"73\" width=\"112\" height=\"132\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"376\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\">模型分数</text><text x=\"376\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">代理变量</text><text x=\"376\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\">总体目标</text><path d=\"M432 139H464\" stroke=\"#7f8b9d\" marker-end=\"url(#bf30)\"/><rect x=\"469\" y=\"73\" width=\"112\" height=\"132\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"525\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\">阈值+人</text><text x=\"525\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">界面/采纳率</text><text x=\"525\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\">申诉</text><path d=\"M581 139H613\" stroke=\"#7f8b9d\" marker-end=\"url(#bf30)\"/><rect x=\"618\" y=\"73\" width=\"118\" height=\"132\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"677\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\">现实结果</text><text x=\"677\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">机会/伤害</text><text x=\"677\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\">新训练数据</text><path d=\"M677 205V274H227V205\" fill=\"none\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\" marker-end=\"url(#bf30)\"/><text x=\"451\" y=\"301\" text-anchor=\"middle\" class=\"svg-t\">选择性标签与反馈：过去没被录用者的真实表现不可见</text></svg><figcaption>图 1　公平是端到端属性；任何一站都可能制造或放大差距。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>标签可能记录历史决策，而不是真实目标<span class=\"dd-badge eng\">测量偏差</span></h2><p class=\"dd-lead\">用“过去被录用且绩效高”训练，模型到底学到了什么？</p><p>未录用者没有绩效标签，观察到的结果受到旧流程选择；绩效评分还受经理、岗位机会和留任影响。模型可能复制“谁过去获得机会”，而非“谁能胜任”。删掉性别字段也无济于事，学校、地址和职业中断可作为代理。</p><p>审查标签的生成过程、缺失机制和测量一致性；用多种结果、人工盲审或自然实验补充。无法获得正当标签时，应缩小用途或把系统用于资源支持，而非高风险排除。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>交叉群体揭示平均指标掩盖的小群体失败<span class=\"dd-badge eng\">切片</span></h2><p class=\"dd-lead\">男女差距很小，是否说明所有女性都被公平对待？</p><p>性别与年龄、地域、残障、语言等交叉后，某小群体可能承受严重错误。切片过细又会样本不足、置信区间极宽，并增加隐私风险。预先基于伤害机制选择重要交叉，而不是事后穷举寻找显著结果。</p><p>报告分母、置信区间和最坏群体表现；对小样本用层级估计、定性研究和人工复核补充，不把噪声排名当确定结论。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>缓解可以发生在数据、学习、阈值和流程四层<span class=\"dd-badge eng\">干预</span></h2><p class=\"dd-lead\">哪一层修复最不容易制造新的不可解释差异？</p><p>数据层改善覆盖、标签和采样；学习层加权或约束目标；后处理调整阈值；流程层改变用途、提供申诉或保证资源。重采样不能修错误标签，阈值调整可能影响校准，复杂约束还会让维护者难以解释版本变化。</p><p>优先修根因和流程，再选择可验证技术；每个干预都同时测总体效用、目标公平指标、非目标群体、校准与稳定性。保护属性有时必须用于测量和纠偏，但应受隐私与访问治理。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>人类复核可能缓解也可能放大模型偏差<span class=\"dd-badge eng\">人机系统</span></h2><p class=\"dd-lead\">加一个招聘官确认按钮，为什么差距可能反而增加？</p><p>人会锚定模型分数、只审查模型标记的样本，或对不同群体采用不同推翻标准。界面若隐藏不确定性并显示伪精确排名，自动化偏见更强。反之，给出相关证据、限制用途、提供独立二次评估和记录理由，可让监督更有效。</p><p>分别测模型建议、最终人类决策、采纳率、推翻率、处理时间和群体结果；公平结论必须针对最终决策链，而非离线模型。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>上线监控需要处理延迟标签和行为反馈<span class=\"dd-badge eng\">持续验证</span></h2><p class=\"dd-lead\">职位变化后，旧评测集为何很快失效？</p><p>岗位、申请人群和招聘官行为变化会改变输入和基率；真实绩效可能数月后才出现，且只对被录用者可见。监测输入覆盖、分数分布、群体通过/推翻/申诉、反馈缺失和标签延迟，设置调查阈值而非自动宣判歧视。</p><p>版本比较必须在共同样本和共同政策下进行；发现差距先检查数据管道、群体编码和分母，再决定回滚、限用或重新评估。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>公平评测要报告绝对量、相对差距与不确定性<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">比率0.8和差值2个百分点，哪个更重要？</p><p>比率对低基率敏感，差值展示实际规模；二者都要配分母、置信区间和伤害严重度。至少报告选择率、TPR、FPR、PPV、校准、最坏群体、交叉切片和随时间稳定性，并说明标签与群体定义。</p><p>阈值不应在测试集上反复调到好看；保留确认集和治理批准。把“公平通过/失败”压成单值会遮蔽互相冲突的指标和受影响者视角。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">12</span>常见误区与概念依赖<span class=\"dd-badge intuition\">误区与学习路线</span></h2><p class=\"dd-lead\">技术公平指标是讨论工具，不是社会公平的完整定义。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>去掉保护属性即公平</td><td>代理变量和历史标签仍可编码群体</td></tr><tr><td>群体样本相等即公平</td><td>标签、机会与错误代价仍可能不同</td></tr><tr><td>一个指标越低越好</td><td>定义之间可能冲突，需情境优先级</td></tr><tr><td>总体模型公平即可</td><td>最终人机流程和反馈决定现实结果</td></tr></tbody></table></div><p><b>学习路线：</b>先学混淆矩阵、校准和因果图，再学公平定义、选择性标签和交叉性；工程上连接隐私、治理、人在回路和持续监控。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义受影响者、决策和不可接受伤害</li><li>审查历史过程、标签与选择机制</li><li>为各群体建立有分母的混淆矩阵</li><li>根据错误代价选择公平关系</li><li>检查定义冲突与不确定性</li><li>在根因最接近的层级实施干预</li><li>评测最终人机决策与交叉群体</li><li>提供申诉并持续监测反馈循环</li></ol>\n      <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>验证层</th><th>在“偏见与公平：先选择要保护的关系，再计算群体差异”中固定什么</th><th>观察什么证据</th></tr></thead><tbody>\n      <tr><td>输入</td><td>同一批样本、前处理与权限边界</td><td>输入哈希、切片标签和拒绝原因</td></tr>\n      <tr><td>机制</td><td>仅改变一个核心变量，其余配置锁定</td><td>关键中间状态及首次偏离预期的位置</td></tr>\n      <tr><td>输出</td><td>同一验收规则与资源预算</td><td>质量、成本、延迟和失败率的分层差异</td></tr>\n      <tr><td>反证</td><td>保留不启用目标机制的对照组</td><td>收益是否跨样本与随机种子稳定复现</td></tr>\n      </tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>样本数平衡为何不保证公平？</li><li>均等机会在案例中的差距是多少？</li><li>公平不可兼得说明什么？</li><li>删掉性别为何可能无效？</li><li>为什么要测最终人机结果？</li><li>假设“偏见与公平：先选择要保护的关系，再计算群体差异”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“偏见与公平：先选择要保护的关系，再计算群体差异”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>历史目标、标签质量、代理变量、阈值和部署流程仍可能制造差异。</li><li>A组TPR 80%，B组60%，差20个百分点。</li><li>不同指标保护不同关系，需要公开价值优先级和剩余伤害。</li><li>学校、地址等代理变量和历史标签仍编码群体信息。</li><li>人会采纳或推翻模型，界面和自动化偏见会改变真实决策差距。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1610.02413\" target=\"_blank\" rel=\"noopener\">Equality of Opportunity in Supervised Learning</a>：均等机会与均等赔率</li><li><a href=\"https://arxiv.org/abs/1609.05807\" target=\"_blank\" rel=\"noopener\">Inherent Trade-Offs in the Fair Determination of Risk Scores</a>：校准与错误率约束的不可兼得</li><li><a href=\"https://fairmlbook.org/\" target=\"_blank\" rel=\"noopener\">Fairness and Machine Learning</a>：公平定义、测量与社会技术视角</li><li><a href=\"https://arxiv.org/abs/1803.09010\" target=\"_blank\" rel=\"noopener\">Datasheets for Datasets</a>：数据集动机、组成与使用文档</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
